final class Vault(store: Store, policy: Policy):
  def withRecord[A](subject: Subject, id: Id)(f: Record => A): A =
    if !policy.allows(subject, id) then throw SecurityException(s"denied: $id")
    else f(store.get(id))      // the only way to touch a Record: it never escapes unmediated
  private def raw(id: Id): Record = store.get(id)   // not reachable from outside
